<div class="page-head"><div><h3>Monthly report</h3><p>Rollup by material with stock, production and movement totals.</p></div><form class="month-form"><input type="month" name="month" value="<?= esc($month) ?>"><button class="primary">Apply</button></form></div><section class="panel"><div class="table-wrap"><table><thead><tr><th>Material</th><th>Opening</th><th>Receipts</th><th>Issued</th><th>Closing</th><th>Physical</th><th>Diff</th><th>Production</th><th>Plan vs Actual</th><th>Reject</th><th>Transfer</th><th>Samples</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><b><?= esc($r['code']) ?></b><small><?= esc($r['description']) ?></small></td><td><?= number_format($r['opening_stock'],3) ?></td><td><?= number_format($r['receipts'],3) ?></td><td><?= number_format($r['issued'],3) ?></td><td><?= number_format($r['closing_stock'],3) ?></td><td><?= number_format($r['physical_stock'],3) ?></td><td><?= number_format($r['difference'],3) ?></td><td><?= number_format($r['production'],3) ?></td><td><?= $r['plan_actual']===null?'—':number_format($r['plan_actual'],1).'%' ?></td><td><?= number_format($r['rejection'],3) ?></td><td><?= number_format($r['transfer'],3) ?></td><td><?= number_format($r['samples'],3) ?></td></tr><?php endforeach; ?></tbody></table></div></section>